const edsType = "type.googleapis.com/envoy.config.endpoint.v3.ClusterLoadAssignment"
func field(number int, value []byte) []byte {
 out:=binary.AppendUvarint(nil,uint64(number<<3|2))
 out=binary.AppendUvarint(out,uint64(len(value)));return append(out,value...)
}
func text(number int,value string)[]byte{return field(number,[]byte(value))}
func integer(number int,value uint64)[]byte{return binary.AppendUvarint(binary.AppendUvarint(nil,uint64(number<<3)),value)}
func join(parts ...[]byte)[]byte{var out []byte;for _,part:=range parts{out=append(out,part...)};return out}
func parse(data []byte)(map[int][][]byte,error){
 out:=map[int][][]byte{}
 for len(data)>0{
  key,n:=binary.Uvarint(data);if n<=0{return nil,fmt.Errorf("bad field key")};data=data[n:]
  number:=int(key>>3)
  switch key&7 {
  case 0:_,n=binary.Uvarint(data);if n<=0{return nil,fmt.Errorf("bad integer")};data=data[n:]
  case 1:if len(data)<8{return nil,io.ErrUnexpectedEOF};data=data[8:]
  case 2:
   size,m:=binary.Uvarint(data);if m<=0||size>uint64(len(data)-m){return nil,io.ErrUnexpectedEOF};data=data[m:]
   out[number]=append(out[number],append([]byte(nil),data[:int(size)]...));data=data[int(size):]
  case 5:if len(data)<4{return nil,io.ErrUnexpectedEOF};data=data[4:]
  default:return nil,fmt.Errorf("unsupported wire type")
  }
 }
 return out,nil
}
func first(fields map[int][][]byte,number int)[]byte{if len(fields[number])==0{return nil};return fields[number][0]}
func frameRead(reader io.Reader)([]byte,error){
 head:=make([]byte,5);if _,e:=io.ReadFull(reader,head);e!=nil{return nil,e}
 if head[0]!=0{return nil,fmt.Errorf("compression outside fixture")}
 n:=binary.BigEndian.Uint32(head[1:]);if n>1048576{return nil,fmt.Errorf("bounded request")}
 data:=make([]byte,n);_,e:=io.ReadFull(reader,data);return data,e
}
func frameWrite(writer io.Writer,data []byte)error{
 head:=make([]byte,5);binary.BigEndian.PutUint32(head[1:],uint32(len(data)))
 if _,e:=writer.Write(head);e!=nil{return e};_,e:=writer.Write(data);return e
}
type State struct{Version string;Nonce string;Resource string;Address string;Port int;Targets []string}
func response(state State)[]byte{
 socket:=join(text(2,state.Address),integer(3,uint64(state.Port)))
 endpoint:=field(1,field(1,socket))
 lbEndpoint:=field(1,endpoint)
 locality:=field(2,lbEndpoint)
 assignment:=join(text(1,state.Resource),field(2,locality))
 any:=join(text(1,edsType),field(2,assignment))
 return join(text(1,state.Version),field(2,any),text(4,edsType),text(5,state.Nonce))
